<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage users | CoworkSpace</title><link rel="stylesheet" href="../assets/style.css"></head><body><header class="navbar"><div class="container nav-content"><a class="logo" href="index.php">Cowork<span>Admin</span></a><nav class="nav-links"><a href="index.php">Dashboard</a><a href="spaces.php">Spaces</a><a href="time-slots.php">Time slots</a><a class="active" href="users.php">Users</a><a href="../logout.php">Log out</a></nav></div></header><main class="section"><div class="container"><div class="section-heading"><div><span class="eyebrow">ACCOUNT ACCESS</span><h1>Manage users</h1></div><a class="btn btn-outline" href="index.php">Back to dashboard</a></div><?php if($message):?><div class="alert success"><?=htmlspecialchars($message)?></div><?php endif;?><div class="table-wrapper"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Joined</th><th>Account</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $u):?><tr><td><?=htmlspecialchars($u["name"])?></td><td><?=htmlspecialchars($u["email"])?></td><td><?=htmlspecialchars(ucfirst($u["role"]))?></td><td><?=htmlspecialchars($u["created_at"])?></td><td><span class="badge <?=((int)$u["is_active"])?"badge-confirmed":"badge-cancelled"?>"><?=((int)$u["is_active"])?"Active":"Deactivated"?></span></td><td><?php if($u["role"]==="user"):?><form method="POST"><input type="hidden" name="user_id" value="<?=(int)$u["id"]?>"><button class="btn btn-small <?=((int)$u["is_active"])?"btn-danger":"btn-outline"?>" name="action" value="<?=((int)$u["is_active"])?"deactivate":"activate"?>"><?=((int)$u["is_active"])?"Deactivate":"Activate"?></button></form><?php else:?><span class="muted">Admin</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></main><footer class="footer"><div class="container">CoworkSpace Admin</div></footer></body></html>
